import{_ as n,a as o,c as t,ac as a}from"./chunks/framework.BSuaGltH.js";const m=JSON.parse('{"title":"第一册：英语初阶 · 全册语法总结 · 主格和宾格至some/any 与存在句疑问","description":"按课时归集语法规则、原创例句和易错边界。","frontmatter":{"title":"第一册：英语初阶 · 全册语法总结 · 主格和宾格至some/any 与存在句疑问","description":"按课时归集语法规则、原创例句和易错边界。","splitFrom":"life/english/new-concept/book-1/grammar.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"句法与表达查阅","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第一册：英语初阶 · 全册语法总结","summary":"按课时归集语法规则、原创例句和易错边界。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · 全册语法总结 · be 动词的一般疑问句至复数职业与 their","link":"/life/english/new-concept/book-1/grammar-part-01"},"next":{"text":"第一册：英语初阶 · 全册语法总结 · can 表能力至过去存在句与时间介词","link":"/life/english/new-concept/book-1/grammar-part-03"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · 全册语法总结 · be 动词的一般疑问句至复数职业与 their","link":"/life/english/new-concept/book-1/grammar-part-01"},"next":{"text":"第一册：英语初阶 · 全册语法总结 · can 表能力至过去存在句与时间介词","link":"/life/english/new-concept/book-1/grammar-part-03"}},"headers":[],"relativePath":"life/english/new-concept/book-1/grammar-part-02.md","filePath":"life/english/new-concept/book-1/grammar-part-02.md"}'),s={name:"life/english/new-concept/book-1/grammar-part-02.md"};function r(i,e,p,h,l,g){return o(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="第一册-英语初阶-·-全册语法总结-·-主格和宾格至some-any-与存在句疑问" tabindex="-1">第一册：英语初阶 · 全册语法总结 · 主格和宾格至some/any 与存在句疑问 <a class="header-anchor" href="#第一册-英语初阶-·-全册语法总结-·-主格和宾格至some-any-与存在句疑问" aria-label="Permalink to &quot;第一册：英语初阶 · 全册语法总结 · 主格和宾格至some/any 与存在句疑问&quot;">​</a></h1><p><a href="/life/english/new-concept/book-1/grammar">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-1/overview">本册介绍</a> · <a href="/life/english/new-concept/book-1/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-1/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-1/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-1/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-1/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-1/review">综合复习与自测</a></p><h2 id="主格和宾格" tabindex="-1">主格和宾格 <a class="header-anchor" href="#主格和宾格" aria-label="Permalink to &quot;主格和宾格 {#主格和宾格}&quot;">​</a></h2><p>主语位置用 I/he/she/we/they，动词或介词后的宾语位置用 me/him/her/us/them。Look at 后需要宾格，如 Look at them。形容词描述人的状态时仍需要 be；多个形容词可用 and 连接。先判断代词在句中的角色，再决定形式，不要只按中文“他们”选 they。</p><p><strong>L19 原创例句：</strong> The runners are tired and hungry.</p><p>跑步的人又累又饿。</p><p><strong>L20 原创例句：</strong> Look at them near the gate.</p><p>看门附近的他们。</p><p><strong>易错：</strong> look at they 应改为 look at them；they 在此不是主语。</p><p><a href="/life/english/new-concept/book-1/unit-01/lesson-019">Lesson 19</a> · <a href="/life/english/new-concept/book-1/unit-01/lesson-020">Lesson 20</a></p><h2 id="which-与-one-的替代" tabindex="-1">which 与 one 的替代 <a class="header-anchor" href="#which-与-one-的替代" aria-label="Permalink to &quot;which 与 one 的替代 {#which-与-one-的替代}&quot;">​</a></h2><p>which 用于在可识别的范围中选择。one 可以替代前面已提到的单数可数名词，以避免重复；如 the red one 表示红色的那个。give 可接双宾语：give + 人 + 物，人的位置用宾格。形容词前是否加 the 取决于是否指向特定选项，不是所有 one 都必须带 the。</p><p><strong>L21 原创例句：</strong> Please give me the empty box.</p><p>请把那个空盒子给我。</p><p><strong>L22 原创例句：</strong> Which notebook do you want: the red one or the blue one?</p><p>你要哪本笔记本：红的还是蓝的？</p><p><strong>易错：</strong> one 替代可数名词单数，不能用来替代不可数的 water。</p><p><a href="/life/english/new-concept/book-1/unit-01/lesson-021">Lesson 21</a> · <a href="/life/english/new-concept/book-1/unit-01/lesson-022">Lesson 22</a></p><h2 id="ones-与复数选择" tabindex="-1">ones 与复数选择 <a class="header-anchor" href="#ones-与复数选择" aria-label="Permalink to &quot;ones 与复数选择 {#ones-与复数选择}&quot;">​</a></h2><p>ones 替代已提到的复数可数名词；the clean ones 指前文的一组干净物品。some 后可接复数可数名词，也可接不可数名词；本课先用 some plates 这样的复数对象。give us/them 中代词是宾格。which glasses 的中心词为复数，回答时不要退回单数 one。</p><p><strong>L23 原创例句：</strong> Please give us the clean plates.</p><p>请把干净的盘子给我们。</p><p><strong>L24 原创例句：</strong> I want the small ones beside the sink.</p><p>我要水槽旁边小的那些。</p><p><strong>易错：</strong> 不能把复数 plates 替换为 one；some 后单数 plate 通常不表示“一些盘子”。</p><p><a href="/life/english/new-concept/book-1/unit-01/lesson-023">Lesson 23</a> · <a href="/life/english/new-concept/book-1/unit-01/lesson-024">Lesson 24</a></p><h2 id="there-is-与位置介词" tabindex="-1">there is 与位置介词 <a class="header-anchor" href="#there-is-与位置介词" aria-label="Permalink to &quot;there is 与位置介词 {#there-is-与位置介词}&quot;">​</a></h2><p>there is 用于引出某处存在的单数物品，后接 a/an + 单数名词；说某个已知物品在哪里则用 The ... is ...。in 表内部，on 表在表面，near 表附近。先区分“这里有一个什么”和“那个东西在哪里”，两种句型的信息起点不同。介词短语本身不能替代句子的谓语。</p><p><strong>L25 原创例句：</strong> There is a clock above the fridge.</p><p>冰箱上方有一只钟。</p><p><strong>L26 原创例句：</strong> The kettle is on the shelf.</p><p>水壶在架子上。</p><p><strong>易错：</strong> There is the kettle 常不适合首次引入物品；首次介绍通常用 a kettle。</p><p><a href="/life/english/new-concept/book-1/unit-02/lesson-025">Lesson 25</a> · <a href="/life/english/new-concept/book-1/unit-02/lesson-026">Lesson 26</a></p><h2 id="there-are-与复数位置" tabindex="-1">there are 与复数位置 <a class="header-anchor" href="#there-are-与复数位置" aria-label="Permalink to &quot;there are 与复数位置 {#there-are-与复数位置}&quot;">​</a></h2><p>there are 后接复数名词，表示某处存在多件物品；问它们在哪里用 Where are they?。between ... and ... 表示在两个参照物之间，next to 表紧邻。there be 不能与 have 混成 There have。已知复数物品作主语时用 They are ...，其中 they 指物品，there 则是存在句的引导成分。</p><p><strong>L27 原创例句：</strong> There are two lamps beside the sofa.</p><p>沙发旁有两盏灯。</p><p><strong>L28 原创例句：</strong> The pictures are between the windows.</p><p>这些画在窗户之间。</p><p><strong>易错：</strong> 不要写 There is two lamps；复数灯需要 are。</p><p><a href="/life/english/new-concept/book-1/unit-02/lesson-027">Lesson 27</a> · <a href="/life/english/new-concept/book-1/unit-02/lesson-028">Lesson 28</a></p><h2 id="祈使句与-must" tabindex="-1">祈使句与 must <a class="header-anchor" href="#祈使句与-must" aria-label="Permalink to &quot;祈使句与 must {#祈使句与-must}&quot;">​</a></h2><p>肯定祈使句通常以动词原形开头，省略主语 you；please 可放句首或句末，句末通常用逗号隔开。must 表示必要或要求，后接动词原形，不加 to。询问要做什么用 What must I do?，将 must 放在主语前。不要把命令与正在发生的动作混淆，Open ... 是要求，不是陈述。</p><p><strong>L29 原创例句：</strong> Please close the cupboard quietly.</p><p>请轻轻关上橱柜。</p><p><strong>L30 原创例句：</strong> I must tidy my desk before lunch.</p><p>午饭前我必须整理书桌。</p><p><strong>易错：</strong> must 后不用 to；must to tidy 应改为 must tidy。</p><p><a href="/life/english/new-concept/book-1/unit-02/lesson-029">Lesson 29</a> · <a href="/life/english/new-concept/book-1/unit-02/lesson-030">Lesson 30</a></p><h2 id="现在进行时单数" tabindex="-1">现在进行时单数 <a class="header-anchor" href="#现在进行时单数" aria-label="Permalink to &quot;现在进行时单数 {#现在进行时单数}&quot;">​</a></h2><p>现在进行时由 am/is/are + 动词 ing 构成，用于描述说话时或现阶段正在进行的动作。he/she/it 用 is，I 用 am。否定词 not 放在 be 后；问句将 be 提前。以不发音 e 结尾的动词通常去 e 加 ing，如 make → making，不能只写动词 ing 而漏掉 be。</p><p><strong>L31 原创例句：</strong> Nora is reading beside the window.</p><p>诺拉正在窗边读书。</p><p><strong>L32 原创例句：</strong> Is the cat sleeping under the chair?</p><p>猫正在椅子下面睡觉吗？</p><p><strong>易错：</strong> Nora reading 缺少 is；问句也不能写 Does Nora is reading。</p><p><a href="/life/english/new-concept/book-1/unit-02/lesson-031">Lesson 31</a> · <a href="/life/english/new-concept/book-1/unit-02/lesson-032">Lesson 32</a></p><h2 id="现在进行时复数" tabindex="-1">现在进行时复数 <a class="header-anchor" href="#现在进行时复数" aria-label="Permalink to &quot;现在进行时复数 {#现在进行时复数}&quot;">​</a></h2><p>复数主语搭配 are + 动词 ing。what are they doing 询问活动，不问职业。并列两个动作且主语相同时可共享 be，如 They are singing and dancing。run、swim 等短元音加单辅音结尾的动词通常双写尾辅音加 ing；walk、read 不需要双写。用 now 强调当前场景。</p><p><strong>L33 原创例句：</strong> The children are drawing by the pond.</p><p>孩子们正在池塘边画画。</p><p><strong>L34 原创例句：</strong> Two dogs are running across the field.</p><p>两只狗正在跑过田野。</p><p><strong>易错：</strong> swim 的 ing 形式是 swimming；不要写 swiming。</p><p><a href="/life/english/new-concept/book-1/unit-02/lesson-033">Lesson 33</a> · <a href="/life/english/new-concept/book-1/unit-02/lesson-034">Lesson 34</a></p><h2 id="位置与方向介词" tabindex="-1">位置与方向介词 <a class="header-anchor" href="#位置与方向介词" aria-label="Permalink to &quot;位置与方向介词 {#位置与方向介词}&quot;">​</a></h2><p>in、on、under、between 主要交代位置；into 表进入内部，out of 表离开内部，across 表横穿表面，along 表沿着。描述地图时先确定参照物，不能把所有中文“在”都翻成 in。存在句介绍地标，进行时说明人正在沿什么路线移动，两类句子可在同一段描述中配合。</p><p><strong>L35 原创例句：</strong> A narrow bridge crosses the river.</p><p>一座窄桥横跨河流。</p><p><strong>L36 原创例句：</strong> The visitors are walking along the river.</p><p>游客正在沿河步行。</p><p><strong>易错：</strong> across 强调横穿，along 强调沿线行进；方向不同不能互换。</p><p><a href="/life/english/new-concept/book-1/unit-02/lesson-035">Lesson 35</a> · <a href="/life/english/new-concept/book-1/unit-02/lesson-036">Lesson 36</a></p><h2 id="be-going-to-表计划" tabindex="-1">be going to 表计划 <a class="header-anchor" href="#be-going-to-表计划" aria-label="Permalink to &quot;be going to 表计划 {#be-going-to-表计划}&quot;">​</a></h2><p>be going to + 动词原形表示事先计划或有迹象的将来；be 随主语变化。be + 动词 ing 在本课表示当前进行。I am making 描述正在做，I am going to make 描述准备做。问计划时将 be 提前：What are you going to make?。to 后不能再用 making，时间词帮助确定语境。</p><p><strong>L37 原创例句：</strong> We are going to paint the bench tomorrow.</p><p>我们准备明天给长凳刷漆。</p><p><strong>L38 原创例句：</strong> I am measuring the shelf now.</p><p>我正在测量架子。</p><p><strong>易错：</strong> going to 后接原形，不能写 going to painting。</p><p><a href="/life/english/new-concept/book-1/unit-02/lesson-037">Lesson 37</a> · <a href="/life/english/new-concept/book-1/unit-02/lesson-038">Lesson 38</a></p><h2 id="否定祈使句与宾语代词" tabindex="-1">否定祈使句与宾语代词 <a class="header-anchor" href="#否定祈使句与宾语代词" aria-label="Permalink to &quot;否定祈使句与宾语代词 {#否定祈使句与宾语代词}&quot;">​</a></h2><p>否定祈使句用 Don&#39;t + 动词原形，可提醒对方不要做某事。动词后用 it/them 指代物品：lift it、move them。计划用 be going to + 动词原形；介词 on 与 onto 的差异在于位置和移动到表面。给出指令时先说明对象，再用代词承接，避免不知道 it 指什么。</p><p><strong>L39 原创例句：</strong> Do not put the wet box on the bed.</p><p>不要把湿盒子放在床上。</p><p><strong>L40 原创例句：</strong> We are going to carry it upstairs.</p><p>我们准备把它搬上楼。</p><p><strong>易错：</strong> 否定指令用 Don&#39;t put，不用 Not put；carry 后的 it 是宾语。</p><p><a href="/life/english/new-concept/book-1/unit-02/lesson-039">Lesson 39</a> · <a href="/life/english/new-concept/book-1/unit-02/lesson-040">Lesson 40</a></p><h2 id="不可数名词与量词" tabindex="-1">不可数名词与量词 <a class="header-anchor" href="#不可数名词与量词" aria-label="Permalink to &quot;不可数名词与量词 {#不可数名词与量词}&quot;">​</a></h2><p>不可数名词通常不直接与 a/an 或数词连用，可用 a bottle of water、a piece of paper 表示可计量单位。计数时改变单位名词，如 two bottles of water，water 不加 s。there is 与不可数名词配合。some 常见于肯定句，any 常见于疑问和否定句，但请求和期待肯定的问句也可用 some。</p><p><strong>L41 原创例句：</strong> There is a bottle of juice in my bag.</p><p>我包里有一瓶果汁。</p><p><strong>L42 原创例句：</strong> Is there any paper in the drawer?</p><p>抽屉里有纸吗？</p><p><strong>易错：</strong> 普通物质义的 paper 不写 a paper；一张纸用 a sheet/piece of paper。</p><p><a href="/life/english/new-concept/book-1/unit-02/lesson-041">Lesson 41</a> · <a href="/life/english/new-concept/book-1/unit-02/lesson-042">Lesson 42</a></p><h2 id="some-any-与存在句疑问" tabindex="-1">some/any 与存在句疑问 <a class="header-anchor" href="#some-any-与存在句疑问" aria-label="Permalink to &quot;some/any 与存在句疑问 {#some-any-与存在句疑问}&quot;">​</a></h2><p>提问某处有没有东西时，将 there be 中的 be 提前：Is there ...? / Are there ...?。不可数名词和单数用 is，复数用 are。any 常用于中性询问及否定；some 可以用于提供食物或期待肯定回答的请求。简短回答用 there is/are，不用 it is/they are 来替代存在句的 there。</p><p><strong>L43 原创例句：</strong> Are there any clean mugs in the cupboard?</p><p>橱柜里有干净的马克杯吗？</p><p><strong>L44 原创例句：</strong> There is not any milk in the fridge.</p><p>冰箱里没有牛奶。</p><p><strong>易错：</strong> 回答 Are there ...? 要用 Yes, there are；不要写 Yes, they are。</p><p><a href="/life/english/new-concept/book-1/unit-02/lesson-043">Lesson 43</a> · <a href="/life/english/new-concept/book-1/unit-02/lesson-044">Lesson 44</a></p>',107)])])}const f=n(s,[["render",r]]);export{m as __pageData,f as default};
